#!/bin/sh
# Update the vendored @mozilla/readability dependency.
#
# Usage: tools/update-readability.sh [TAG]
#   TAG defaults to the newest upstream release tag.
#
# Refreshes vendor/readability/Readability.js and vendor/readability/
# pinned-version. The embedded OCaml copy (lib/readability_js.ml) is
# regenerated by dune on the next build.
set -eu

repo_dir=$(cd "$(dirname "$0")/.." && pwd)
upstream="https://github.com/mozilla/readability"
raw_base="https://raw.githubusercontent.com/mozilla/readability"
dest="$repo_dir/vendor/readability"

tag=${1:-}

if [ -z "$tag" ]; then
  echo "Looking up the newest mozilla/readability release tag..." >&2
  tag=$(curl -fsSL "$upstream/tags" -H 'Accept: application/vnd.github+json' \
    | sed -n 's/.*"name": "\([0-9][0-9.]*\)".*/\1/p' | head -n 1)
fi

echo "$tag" | grep -Eq '^[0-9]+(\.[0-9]+)*$' ||
  { echo "Invalid version tag: $tag" >&2; exit 1; }

echo "Fetching mozilla/readability $tag..." >&2
curl -fsSL -o "$dest/Readability.js.new" "$raw_base/$tag/Readability.js" ||
  { echo "Fetch failed for tag $tag" >&2; exit 1; }

if [ ! -s "$dest/Readability.js.new" ]; then
  echo "Fetched file is empty; refusing to update" >&2
  rm -f "$dest/Readability.js.new"
  exit 1
fi

# The build embeds the file in an OCaml quoted string delimited by
# __readability_string__; refuse content that would break out of it.
if grep -q '|__readability_string__|' "$dest/Readability.js.new"; then
  echo "Upstream content contains the embedding delimiter; manual review required" >&2
  rm -f "$dest/Readability.js.new"
  exit 1
fi

mv "$dest/Readability.js.new" "$dest/Readability.js"
echo "$tag" > "$dest/pinned-version"
echo "Updated vendor/readability to mozilla/readability $tag" >&2
echo "Remember to run: make build && dune runtest" >&2
